import React from 'react';
import renderer, {act} from 'react-test-renderer';
import {describe, expect, it, jest} from '@jest/globals';
import {StyleSheet} from 'react-native';
import CameraHud from '../src/hud/CameraHud';
import {batteryText, exposureReading, hudSafeBounds} from '../src/hud/readings';
import {CameraState} from '../src/native';
import {scopePanelLayout} from '../src/scopes/panelState';

const connected: CameraState = {active: true, busy: false, ready: true, demo: false, transport: 'usb', lut: null};
function hud(state: CameraState, motion = false, buffered = 3) {
  let tree: renderer.ReactTestRenderer;
  act(() => {tree = renderer.create(<CameraHud state={state} buffered={buffered} motion={motion} waiting={false} onTopLayout={jest.fn()} onBottomLayout={jest.fn()}/>);});
  return tree!;
}
const text = (tree: renderer.ReactTestRenderer, id: string) => tree.root.findByProps({testID: id}).props.children;

describe('truthful four-corner camera HUD', () => {
  it('renders the existing USB exposure, real phone battery, unavailable camera battery and LUT without scopes', () => {
    const tree = hud({...connected, exposure: 'ISO AUTO     f/4.0     1/80', exposureAgeMs: 10, phoneBattery: {percent: 37, charging: true}, lut: 'Fuji 风格 · Classic Chrome'});
    expect(text(tree, 'hud-aperture')).toBe('f/4.0');expect(text(tree, 'hud-shutter')).toBe('1/80');expect(text(tree, 'hud-iso')).toBe('ISO AUTO');
    expect(tree.root.findByProps({accessibilityLabel: '手机电量37%，充电中'})).toBeTruthy();
    expect(tree.root.findByProps({accessibilityLabel: '相机电量不可用，当前连接未提供机身电量'})).toBeTruthy();
    const json = JSON.stringify(tree.toJSON());
    expect(json).toContain('USB · 已连接');expect(json).toContain('Classic Chrome');expect(json).toContain('可拍');expect(json).not.toContain('scopes-overlay');
    for (const id of ['hud-source', 'hud-batteries', 'hud-exposure', 'hud-capture']) expect(tree.root.findByProps({testID: id})).toBeTruthy();
    expect(StyleSheet.flatten(tree.root.findByProps({testID: 'hud-top'}).props.style).zIndex).toBe(1000);
    act(() => tree.unmount());
  });
  it.each([
    ['ISO 800', 'ISO 800', 'f/—', '快门 —'],
    ['f/5.6     快门 1/250', 'ISO —', 'f/5.6', '1/250'],
    ['ISO AUTO     f/2.0     0.8s', 'ISO AUTO', 'f/2.0', '0.8s'],
    ['ISO 100     f/8.0     BULB', 'ISO 100', 'f/8.0', 'BULB'],
  ])('preserves partial / auto / long exposure readings: %s', (exposure, iso, aperture, shutter) => {
    const tree = hud({...connected, exposure});
    expect(text(tree, 'hud-iso')).toBe(iso);expect(text(tree, 'hud-aperture')).toBe(aperture);expect(text(tree, 'hud-shutter')).toBe(shutter);
    act(() => tree.unmount());
  });
  it('preserves unrecognized Wi-Fi encodings and camera messages verbatim, with explicit field placeholders', () => {
    for (const raw of ['ISO 800     f/1024/256     快门 256/65400', 'f/400     快门 256/65400', 'f/28', '曝光参数暂不可读 · 可用机身调整', 'ISO 100 F4 1/60']) {
      const tree = hud({...connected, transport: 'wifi', exposure: raw, exposureAgeMs: 0});
      const json = JSON.stringify(tree.toJSON());
      expect(text(tree, 'hud-aperture')).toBe('f/—');
      expect(text(tree, 'hud-shutter')).toBe('快门 —');
      expect(json).toContain('未经真机验证');
      expect(text(tree, 'hud-exposure-detail')).toBe(raw.split(/\s{2,}/).filter(part => !/^ISO (?:[1-9]\d*|AUTO)$/.test(part)).join(' · '));
      act(() => tree.unmount());
    }
  });
  it('labels aged / unknown-age readings, and discards previous real-camera values in demo or disconnected states', () => {
    const exposure = 'ISO 640     f/2.8     1/125';
    expect(exposureReading({...connected, exposure, exposureAgeMs: 11_000}).label).toContain('已过期');
    expect(exposureReading({...connected, exposure}).label).toContain('最近读数');
    for (const state of [{...connected, exposure, demo: true}, {...connected, exposure, active: false}]) {
      const tree = hud(state, true);
      expect(text(tree, 'hud-aperture')).toBe('f/—');expect(text(tree, 'hud-iso')).toBe('ISO —');
      expect(JSON.stringify(tree.toJSON())).not.toContain('640');
      act(() => tree.unmount());
    }
  });
  it('uses explicit placeholders for unavailable / invalid batteries and keeps a real zero percent', () => {
    for (const percent of [null, -1, 101, NaN, Infinity]) expect(batteryText({percent})).toBe('—');
    expect(batteryText()).toBe('—');expect(batteryText({percent: 0})).toBe('0%');
    const tree = hud({...connected, phoneBattery: {percent: 0}, cameraBattery: {percent: 45}});
    expect(tree.root.findByProps({accessibilityLabel: '手机电量0%'})).toBeTruthy();
    expect(tree.root.findByProps({accessibilityLabel: '相机电量45%'})).toBeTruthy();
    act(() => tree.unmount());
  });
  it('shows capture processing and motion-buffer status without inventing exposure or invalid buffer durations', () => {
    const tree = hud({...connected, busy: true}, true, NaN);
    expect(JSON.stringify(tree.toJSON())).toContain('处理中…');expect(JSON.stringify(tree.toJSON())).not.toContain('NaN');
    act(() => tree.unmount());
    const motion = hud(connected, true, 4.5);
    expect(JSON.stringify(motion.toJSON())).toContain('缓存就绪');expect(JSON.stringify(motion.toJSON())).toContain('3.0');
    act(() => motion.unmount());
  });
  it('keeps compact, enlarged and dragged charts inside measured HUD space in portrait, landscape and font 1.3', () => {
    for (const [width, height, top, bottom] of [[360, 540, 52, 52], [600, 360, 52, 52], [360, 540, 72, 88], [480, 320, 72, 88]]) {
      const bounds = hudSafeBounds({width, height}, top, bottom);
      for (const size of ['S', 'M'] as const) for (const slot of [0, 1, 2, 3, undefined]) {
        const panel = scopePanelLayout(bounds, {x: 1, y: 1}, size, slot);
        expect(panel.x).toBeGreaterThanOrEqual(bounds.insets!.left);expect(panel.x + panel.width).toBeLessThanOrEqual(width - bounds.insets!.right);
        expect(panel.y).toBeGreaterThanOrEqual(bounds.insets!.top);expect(panel.y + panel.height).toBeLessThanOrEqual(height - bounds.insets!.bottom);
      }
    }
  });
});

import React from 'react';
import renderer, {act} from 'react-test-renderer';
import {AppState} from 'react-native';
import {afterEach, expect, it, jest} from '@jest/globals';
import useCameraReadings from '../src/hud/useCameraReadings';
import {camera, CameraState} from '../src/native';

jest.mock('../src/native', () => ({camera: {getState: jest.fn()}}));
const state: CameraState = {active: true, busy: false, ready: true, demo: false, transport: 'usb', lut: null};
function Harness({visible = true, update}: {visible?: boolean; update: React.Dispatch<React.SetStateAction<CameraState>>}) {
  useCameraReadings(state, update, visible);return null;
}
afterEach(() => {jest.clearAllTimers();jest.useRealTimers();jest.restoreAllMocks();});

it('refreshes cached readings in foreground only and removes the state subscription / timer on unmount', async () => {
  jest.useFakeTimers();AppState.currentState = 'active';
  const getState = jest.mocked(camera!.getState);getState.mockReset().mockResolvedValue({...state, exposureAgeMs: 20_000});
  const remove = jest.fn();let changed: (next: string) => void;
  jest.spyOn(AppState, 'addEventListener').mockImplementation((_, handler: any) => {changed = handler;return {remove};});
  const update = jest.fn();let tree: renderer.ReactTestRenderer;
  act(() => {tree = renderer.create(<Harness update={update}/>);});
  await act(async () => {jest.advanceTimersByTime(1000);});
  expect(getState).toHaveBeenCalledTimes(1);expect(update).toHaveBeenCalledWith({...state, exposureAgeMs: 20_000});
  AppState.currentState = 'background';await act(async () => {jest.advanceTimersByTime(3000);});
  expect(getState).toHaveBeenCalledTimes(1);
  AppState.currentState = 'active';await act(async () => changed!('active'));
  expect(getState).toHaveBeenCalledTimes(2);
  act(() => tree!.update(<Harness visible={false} update={update}/>));
  await act(async () => {jest.advanceTimersByTime(3000);});
  expect(getState).toHaveBeenCalledTimes(2);expect(remove).toHaveBeenCalledTimes(1);
  act(() => tree!.unmount());expect(jest.getTimerCount()).toBe(0);
});

it('does not overlap slow reads or apply late state to a workspace that has closed', async () => {
  jest.useFakeTimers();AppState.currentState = 'active';
  let resolve: (value: CameraState) => void;
  const getState = jest.mocked(camera!.getState);getState.mockReset().mockImplementation(() => new Promise(done => {resolve = done;}));
  const update = jest.fn();let tree: renderer.ReactTestRenderer;
  act(() => {tree = renderer.create(<Harness update={update}/>);});
  await act(async () => {jest.advanceTimersByTime(3000);});expect(getState).toHaveBeenCalledTimes(1);
  act(() => tree!.unmount());await act(async () => resolve!(state));
  expect(update).not.toHaveBeenCalled();expect(jest.getTimerCount()).toBe(0);
});

import React from 'react';
import renderer, {act} from 'react-test-renderer';
import {AppState} from 'react-native';
import {afterEach, beforeEach, expect, it, jest} from '@jest/globals';

jest.mock('react-native-safe-area-context', () => ({SafeAreaView: ({children}: any) => children}));
jest.mock('../src/native', () => ({camera: {capture: jest.fn(), captureStill: jest.fn(), focus: jest.fn(), setAudio: jest.fn()}}));
jest.mock('../src/microphonePermission', () => ({requestMicrophonePermission: jest.fn(async () => true)}));

import CameraWorkspace from '../src/CameraWorkspace';
import {camera, CameraState} from '../src/native';
import {requestMicrophonePermission} from '../src/microphonePermission';

const state: CameraState = {active: true, busy: false, ready: true, demo: false, lut: null};
const props = {state, buffered: 3, luts: [], onAlbum: jest.fn(), onLut: async () => {}, onImportLut: async () => {}, onRefresh: async () => {}, onConnect: async () => {}};
let tree: renderer.ReactTestRenderer;

beforeEach(() => {
  jest.useFakeTimers(); jest.clearAllMocks(); AppState.currentState = 'active';
  jest.mocked(requestMicrophonePermission).mockResolvedValue(true);
  act(() => { tree = renderer.create(<CameraWorkspace {...props}/>); });
});
afterEach(() => { act(() => tree.unmount()); jest.clearAllTimers(); jest.useRealTimers(); jest.restoreAllMocks(); });
const press = (label: string) => act(() => tree.root.findByProps({accessibilityLabel: label}).props.onPress());
const tick = (ms: number) => act(() => jest.advanceTimersByTime(ms));

it('removes the AF, near and far focus cluster', () => {
  for (const label of ['自动对焦', '近对焦', '远对焦']) expect(tree.root.findAllByProps({accessibilityLabel: label})).toHaveLength(0);
});

it('captures an ordinary still with no prebuffer and with a selected LUT', () => {
  act(() => tree.update(<CameraWorkspace {...props} state={{...state, ready: false, lut: 'Classic Chrome'}} buffered={0}/>));
  press('拍摄照片');
  expect(camera!.captureStill).toHaveBeenCalledTimes(1);
  expect(camera!.capture).not.toHaveBeenCalled();
});

it('uses the current motion setting when the countdown completes exactly once', () => {
  press('定时'); press('开始倒计时'); tick(1000); press('动态照片'); tick(9000);
  expect(camera!.capture).toHaveBeenCalledTimes(1);
  expect(camera!.captureStill).not.toHaveBeenCalled();
  tick(1000); expect(camera!.capture).toHaveBeenCalledTimes(1);
});

it('does not move the countdown when the wall clock changes', () => {
  press('定时'); press('开始倒计时');
  jest.setSystemTime(Date.now() + 60_000); tick(9900);
  expect(camera!.captureStill).not.toHaveBeenCalled();
  tick(100); expect(camera!.captureStill).toHaveBeenCalledTimes(1);
});

it('still cancels immediately when the timer control is pressed during a countdown', () => {
  press('定时'); press('开始倒计时'); tick(5000); press('定时'); tick(6000);
  expect(camera!.captureStill).not.toHaveBeenCalled();
  expect(camera!.capture).not.toHaveBeenCalled();
  expect(tree.root.findByProps({accessibilityLabel: '拍摄照片'})).toBeTruthy();
});

it.each([{busy: true}, {active: false}])('cancels the countdown when capture becomes unavailable: %j', update => {
  press('定时'); press('开始倒计时'); tick(5000);
  act(() => tree.update(<CameraWorkspace {...props} state={{...state, ...update}}/>)); tick(6000);
  expect(camera!.capture).not.toHaveBeenCalled(); expect(camera!.captureStill).not.toHaveBeenCalled();
});

it('checks current prebuffer readiness at the countdown boundary', () => {
  press('动态照片'); press('定时'); press('拍摄动态照片');
  act(() => tree.update(<CameraWorkspace {...props} state={{...state, ready: false}}/>)); tick(10_000);
  expect(camera!.capture).not.toHaveBeenCalled(); expect(camera!.captureStill).not.toHaveBeenCalled();
});

it('cancels before entering the album or unmounting', () => {
  press('定时'); press('开始倒计时'); press('打开相册'); tick(10_000);
  expect(props.onAlbum).toHaveBeenCalledTimes(1); expect(camera!.captureStill).not.toHaveBeenCalled();
  press('开始倒计时'); act(() => tree.unmount()); tick(10_000);
  expect(camera!.captureStill).not.toHaveBeenCalled();
});

it('cancels in background even before a queued tick runs', () => {
  press('定时'); press('开始倒计时'); AppState.currentState = 'background'; tick(10_000);
  expect(camera!.captureStill).not.toHaveBeenCalled();
});

it('keeps audio off when microphone permission is denied', async () => {
  jest.mocked(requestMicrophonePermission).mockResolvedValue(false);
  await act(async () => tree.root.findByProps({accessibilityLabel: '环境声'}).props.onPress());
  expect(requestMicrophonePermission).toHaveBeenCalledTimes(1); expect(camera!.setAudio).not.toHaveBeenCalled();
});

it('restores the native audio preference and switches it off without another permission request', async () => {
  act(() => tree.update(<CameraWorkspace {...props} state={{...state, audio: true}}/>));
  await act(async () => tree.root.findByProps({accessibilityLabel: '环境声'}).props.onPress());
  expect(requestMicrophonePermission).not.toHaveBeenCalled(); expect(camera!.setAudio).toHaveBeenCalledWith(false);
});

it('hides the AF reticle until a feed is available and separates capture modes', () => {
  expect(tree.root.findAllByProps({accessibilityLabel: '中央自动对焦'})).toHaveLength(0);
  act(() => tree.update(<CameraWorkspace {...props} preview="data:image/jpeg;base64,frame"/>));
  expect(tree.root.findByProps({accessibilityLabel: '中央自动对焦'})).toBeTruthy();
  press('动态照片'); press('普通照片'); press('拍摄照片');
  expect(camera!.captureStill).toHaveBeenCalledTimes(1);
  expect(camera!.capture).not.toHaveBeenCalled();
});

import React from 'react';
import renderer, {act} from 'react-test-renderer';
import {expect, it, jest, beforeEach, afterEach} from '@jest/globals';
import {PermissionsAndroid, Platform} from 'react-native';
import {Button, Switch, TextInput, Text} from 'react-native-paper';

jest.mock('react-native-safe-area-context', () => ({SafeAreaView: ({children}: any) => children}));
jest.mock('../src/native', () => ({camera: {capture: jest.fn(), remoteShutter: jest.fn(), focus: jest.fn(), setAudio: jest.fn()}}));
import ConnectionSheet from '../src/connection/ConnectionSheet';
import ExperimentalWifiBadge from '../src/connection/ExperimentalWifiBadge';
import {connectionOptions, initialConnectionForm} from '../src/connection/model';
import CameraWorkspace from '../src/CameraWorkspace';

const state = {active: false, busy: false, ready: false, demo: false, lut: null};
const props = {visible: true, state, status: '', debugAllowed: true, onClose: jest.fn(), onUsb: jest.fn(async () => {}), onWifi: jest.fn(async () => {}), onDemo: jest.fn(async () => {}), onDisconnect: jest.fn()};
let tree: renderer.ReactTestRenderer;
const originalPlatform = Platform.OS;
beforeEach(() => {Platform.OS = 'android'; jest.useFakeTimers(); jest.clearAllMocks(); act(() => {tree = renderer.create(<ConnectionSheet {...props}/>);});});
afterEach(() => {act(() => tree.unmount()); jest.clearAllTimers(); jest.useRealTimers(); jest.restoreAllMocks(); Platform.OS = originalPlatform;});
const button = (label: string) => tree.root.findAllByType(Button).find(node => node.props.accessibilityLabel === label)!;
const toggle = (label: string) => tree.root.findAllByType(Switch).find(node => node.props.accessibilityLabel === label)!;
const wifi = () => act(() => button('Wi-Fi 实验连接方式').props.onPress());

it('defaults to USB and gives Wi-Fi an explicit experimental badge', async () => {
  await act(async () => button('连接 USB 相机').props.onPress());
  expect(props.onUsb).toHaveBeenCalledTimes(1); expect(props.onWifi).not.toHaveBeenCalled();
  wifi(); expect(tree.root.findAllByType(Text).some(node => node.props.children === '实验性 · 未经真机验证')).toBe(true);
  await act(async () => button('连接 Wi-Fi 实验相机').props.onPress());
  expect(props.onWifi).toHaveBeenCalledWith({manual: true, cameraIp: '192.168.54.1'});
});
it('validates known SSID and requests permission only for automatic joining', async () => {
  const permission = jest.spyOn(PermissionsAndroid, 'check').mockResolvedValue(false);
  const request = jest.spyOn(PermissionsAndroid, 'request').mockResolvedValue(PermissionsAndroid.RESULTS.DENIED);
  wifi(); act(() => toggle('已手动连接相机 Wi-Fi').props.onValueChange(false));
  await act(async () => button('连接 Wi-Fi 实验相机').props.onPress());
  expect(props.onWifi).not.toHaveBeenCalled(); expect(permission).not.toHaveBeenCalled();
