        <Pressable onPress={() => { setSelectedId(moment.id); setShowList(false); }} accessibilityRole="button" accessibilityLabel={'打开' + (moment.source || '照片')} style={({pressed}) => [styles.listSelect, pressed && styles.listItemPressed]}>
          <View>
