export type WifiConnectionOptions = {manual: boolean; cameraIp: string; ssid?: string; password?: string; debugEndpoint?: string; udpPort?: number};
export type ConnectionForm = {manual: boolean; cameraIp: string; ssid: string; password: string; debug: boolean; debugEndpoint: string; udpPort: string};
export const initialConnectionForm: ConnectionForm = {manual: true, cameraIp: '192.168.54.1', ssid: '', password: '', debug: false, debugEndpoint: '10.0.2.2:18080', udpPort: '49152'};

export function connectionOptions(form: ConnectionForm, debugAllowed: boolean): WifiConnectionOptions {
  if (form.debug) {
    if (!debugAllowed) throw new Error('模拟相机调试仅限 debug APK');
    const endpoint = form.debugEndpoint.trim();
    if (!/^[A-Za-z0-9.-]+:[0-9]+$/.test(endpoint) || Number(endpoint.split(':')[1]) < 1 || Number(endpoint.split(':')[1]) > 65535) throw new Error('请输入调试主机:端口');
    const udpPort = Number(form.udpPort);
    if (!/^[0-9]+$/.test(form.udpPort) || !Number.isInteger(udpPort) || udpPort < 1 || udpPort > 65535) throw new Error('UDP 端口须为 1–65535');
    return {manual: true, cameraIp: form.cameraIp.trim(), debugEndpoint: endpoint, udpPort};
  }
  const cameraIp = form.cameraIp.trim();
  const ip = cameraIp.split('.');
  if (ip.length !== 4 || ip.some(part => !/^[0-9]{1,3}$/.test(part) || Number(part) > 255)) throw new Error('请输入相机 IPv4 地址');
  if (!form.manual && !form.ssid.trim()) throw new Error('请输入相机 Wi-Fi SSID');
  return {manual: form.manual, cameraIp, ...(form.manual ? {} : {ssid: form.ssid, password: form.password})};
}

import {BatteryReading, CameraState} from '../native';
import {ScopeBounds} from '../scopes/panelState';
import {ui} from '../theme';

export const EXPOSURE_STALE_MS = 10_000;
const EMPTY = {aperture: 'f/—', shutter: '快门 —', iso: 'ISO —'};

/** Only split the display forms emitted by USB / Wi-Fi. Encoded Wi-Fi values stay raw. */
export function exposureReading(state: CameraState) {
  if (!state.active) return {...EMPTY, label: '曝光 · 未连接', detail: ''};
  if (state.demo) return {...EMPTY, label: '曝光 · 演示无读数', detail: ''};
  const raw = state.exposure?.trim() || '';
  const values = {...EMPTY};
  const unparsed: string[] = [];
  for (const part of raw.split(/\s{2,}/).filter(Boolean)) {
    // USB produces a decimal f-number. Bare integers / fractions may be Wi-Fi enums.
    const aperture = /^f\/(\d+\.\d+)$/i.exec(part);
    if (/^ISO (?:[1-9]\d*|AUTO)$/i.test(part)) values.iso = part;
    else if (aperture && Number(aperture[1]) > 0 && Number(aperture[1]) <= 128) values.aperture = part;
    else if (/^(?:快门 )?(?:1\/[1-9]\d*(?:\.\d+)?|(?:[1-9]\d*(?:\.\d+)?|0\.\d+)s|BULB|B)$/i.test(part)) values.shutter = part.replace(/^快门 /, '');
    else unparsed.push(part);
  }
  const available = Object.entries(values).some(([key, value]) => value !== EMPTY[key as keyof typeof EMPTY]);
  const knownAge = typeof state.exposureAgeMs === 'number' && Number.isFinite(state.exposureAgeMs) && state.exposureAgeMs >= 0;
  const label = raw && knownAge && state.exposureAgeMs! > EXPOSURE_STALE_MS ? '曝光 · 上次读数已过期' : !available ? '曝光 · 未提供完整读数' : !knownAge ? '曝光 · 最近读数' : '曝光';
  // A successful preview / state refresh is not evidence of a new exposure sample.
  return {...values, label, detail: unparsed.join(' · ') || (!raw ? '机身未提供读数' : '')};
}

export function batteryText(reading?: BatteryReading | null) {
  const value = reading?.percent;
  return typeof value === 'number' && Number.isFinite(value) && value >= 0 && value <= 100 ? `${Math.round(value)}%` : '—';
}

/** Insets include the physical corner margins and a quiet gap around the measured HUD. */
export function hudSafeBounds(frame: {width: number; height: number}, top: number, bottom: number): ScopeBounds {
  return {...frame, insets: {top: ui.space.gutter + Math.max(0, top) + ui.space.sm, bottom: ui.space.gutter + Math.max(0, bottom) + ui.space.sm, left: ui.space.gutter, right: ui.space.gutter}};
}

import {Dispatch, SetStateAction, useEffect} from 'react';
import {AppState} from 'react-native';
import {camera, CameraState} from '../native';

/** getState reads cached native telemetry only; never enqueue camera I/O for the HUD. */
export default function useCameraReadings(state: CameraState, setState: Dispatch<SetStateAction<CameraState>>, visible: boolean) {
  useEffect(() => {
    if (!visible || !state.active || !camera) return;
    let current = true, pending = false;
    const read = async () => {
      if (!current || pending || AppState.currentState !== 'active') return;
      pending = true;
      try {
        const next = await camera!.getState();
        if (current && AppState.currentState === 'active') setState(next);
      } catch { /* A reading failure never interrupts preview or capture. */ }
      finally {pending = false;}
    };
    const timer = setInterval(() => {void read();}, 1000);
    const subscription = AppState.addEventListener('change', next => {if (next === 'active') void read();});
    return () => {current = false; clearInterval(timer); subscription.remove();};
  }, [state.active, state.demo, state.transport, setState, visible]);
}

import {Alert, PermissionsAndroid, Platform} from 'react-native';

export async function requestMicrophonePermission(): Promise<boolean> {
  if (Platform.OS !== 'android') return true;
  try {
    const permission = PermissionsAndroid.PERMISSIONS.RECORD_AUDIO;
    if (await PermissionsAndroid.check(permission)) return true;
    const result = await PermissionsAndroid.request(permission, {
      title: '录制环境声',
      message: '动态照片可使用手机麦克风收音。允许后，仅在前台连接相机时录制。',
      buttonPositive: '允许',
      buttonNegative: '取消',
    });
    if (result === PermissionsAndroid.RESULTS.GRANTED) return true;
    Alert.alert('未开启环境声', '没有麦克风权限，本次动态照片将保持无声。可在系统设置中允许录音权限。');
  } catch (e) {
    Alert.alert('未开启环境声', String((e as Error)?.message || e));
  }
  return false;
}

import React, {useMemo} from 'react';
import Svg, {Circle, G, Line, Path, Rect, Text as SvgText} from 'react-native-svg';
import {ScopeKind, SCOPE_TITLES} from './panelState';
import {ScopeFrame, SCOPE_SHAPE} from './protocol';

const RGB = ['#FF6B70', '#65ED99', '#6EA9FF'];
const INK = '#DCE7D1';
const GRID = '#FFFFFF70';
const DENSITY_STEPS = 6;

/** One path per intensity band, rather than thousands of React/SVG rect nodes. */
export function densityPaths(data: Uint8Array, columns: number): string[] {
  const paths = new Array<string>(DENSITY_STEPS).fill('');
  for (let i = 0; i < data.length; i++) {
    const value = data[i];
    if (value) paths[Math.min(DENSITY_STEPS - 1, Math.floor(value * DENSITY_STEPS / 256))] +=
      `M${i % columns} ${Math.floor(i / columns)}h1v1h-1z`;
  }
  return paths;
}

function Density({paths, color}: {paths: string[]; color: string}) {
  return <>{paths.map((d, i) => d && <Path key={i} d={d} fill={color} opacity={(i + 1) / DENSITY_STEPS}/>)}</>;
}

function LevelGrid({axisSize}: {axisSize: number}) {
  return <>
    <Rect x={24} y={6} width={256} height={120} fill="none" stroke={GRID}/>
    {[0, 25, 50, 75, 100].map(level => <Line key={level} x1={24} x2={280} y1={126 - level * 1.2} y2={126 - level * 1.2} stroke={GRID}/>)}
    {[0, 50, 100].map(level => <SvgText stroke="#000A" strokeWidth={.55} key={level} x={20} y={129 - level * 1.2} fontSize={axisSize} textAnchor="end" fill={INK}>{level}</SvgText>)}
  </>;
}

function histogramPaths(data: Uint8Array) {
  return [0, 1, 2, 3].map(channel => {
    let path = 'M24 126';
    for (let bin = 0; bin < SCOPE_SHAPE.histogramBins; bin++) path += `L${24 + bin} ${(126 - data[channel * 256 + bin] * 120 / 255).toFixed(1)}`;
    return path + 'L280 126Z';
  });
}

function vectorTarget(r: number, g: number, b: number) {
  const y = .2126 * r + .7152 * g + .0722 * b;
  return {x: 84 + ((b - y) / 1.8556 + .5) * 120, y: 6 + (.5 - (r - y) / 1.5748) * 120};
}
const TARGETS = [
  {name: 'R', color: RGB[0], ...vectorTarget(.75, 0, 0)},
  {name: 'G', color: RGB[1], ...vectorTarget(0, .75, 0)},
  {name: 'B', color: RGB[2], ...vectorTarget(0, 0, .75)},
  {name: 'Y', color: '#F3E986', ...vectorTarget(.75, .75, 0)},
  {name: 'C', color: '#83ECEF', ...vectorTarget(0, .75, .75)},
  {name: 'M', color: '#EDA2EA', ...vectorTarget(.75, 0, .75)},
];

export default React.memo(function ScopePlot({kind, data, displayWidth = 184, displayHeight = 104}: {kind: ScopeKind; data: ScopeFrame; displayWidth?: number; displayHeight?: number}) {
  const plotScale = Math.min(Math.max(1, displayWidth) / (kind === 'vectorscope' ? 136 : 316), Math.max(1, displayHeight) / 150);
  const axisSize = Math.min(28, 9 / plotScale);
  const paths = useMemo(() => {
    if (kind === 'histogram') return [histogramPaths(data.histogram)];
    if (kind === 'waveform') return [densityPaths(data.waveform, SCOPE_SHAPE.waveWidth)];
    if (kind === 'vectorscope') return [densityPaths(data.vectorscope, SCOPE_SHAPE.vectorSize)];
    const size = SCOPE_SHAPE.paradeWidth * SCOPE_SHAPE.levels;
    return [0, 1, 2].map(channel => densityPaths(data.parade.subarray(channel * size, (channel + 1) * size), SCOPE_SHAPE.paradeWidth));
  }, [kind, data]);
  return <Svg width="100%" height="100%" preserveAspectRatio="xMidYMid meet" viewBox={kind === 'vectorscope' ? '0 0 136 150' : '-28 0 316 150'} accessibilityLabel={`${SCOPE_TITLES[kind]} 实时图表`}>
    {kind === 'histogram' && <>
      <Rect x={24} y={6} width={256} height={120} fill="none" stroke={GRID}/>
      {[64, 128, 192].map(bin => <Line key={bin} x1={24 + bin} x2={24 + bin} y1={6} y2={126} stroke={GRID}/>)}
      {paths[0].map((d, i) => <Path key={i} d={d} fill={i === 3 ? 'none' : RGB[i]} fillOpacity={.13} stroke={i === 3 ? INK : RGB[i]} strokeWidth={1.2}/>)}
      <SvgText stroke="#000A" strokeWidth={.55} x={24} y={139} fill={INK} fontSize={axisSize}>0</SvgText><SvgText stroke="#000A" strokeWidth={.55} x={280} y={139} textAnchor="end" fill={INK} fontSize={axisSize}>255</SvgText>
      {[...RGB, INK].map((color, i) => <SvgText stroke="#000A" strokeWidth={.55} key={color} x={112 + i * 18} y={144} fill={color} fontSize={axisSize}>{['R', 'G', 'B', 'Y'][i]}</SvgText>)}
    </>}
    {kind === 'waveform' && <>
      <LevelGrid axisSize={axisSize}/><G transform="translate(24 6) scale(4 1.875)"><Density paths={paths[0]} color={INK}/></G>
      <SvgText stroke="#000A" strokeWidth={.55} x={24} y={143} fill={INK} fontSize={axisSize}>L</SvgText><SvgText stroke="#000A" strokeWidth={.55} x={280} y={143} textAnchor="end" fill={INK} fontSize={axisSize}>R</SvgText>
    </>}
    {kind === 'parade' && <>
      <LevelGrid axisSize={axisSize}/>{RGB.map((color, i) => <G key={color}>
        <G transform={`translate(${24 + i * 256 / 3} 6) scale(${256 / 3 / 32} 1.875)`}><Density paths={paths[i]} color={color}/></G>
        {i > 0 && <Line x1={24 + i * 256 / 3} x2={24 + i * 256 / 3} y1={6} y2={126} stroke={GRID}/>}
        <SvgText stroke="#000A" strokeWidth={.55} x={24 + (i + .5) * 256 / 3} y={143} textAnchor="middle" fill={color} fontSize={axisSize}>{['R', 'G', 'B'][i]}</SvgText>
      </G>)}
    </>}
    {kind === 'vectorscope' && <G transform="translate(-76 0)">
      <Circle cx={144} cy={66} r={60} fill="none" stroke={GRID}/>
      <Circle cx={144} cy={66} r={30} fill="none" stroke={GRID}/>
      <Line x1={84} x2={204} y1={66} y2={66} stroke={GRID}/><Line x1={144} x2={144} y1={6} y2={126} stroke={GRID}/>
      <G transform="translate(84 6) scale(1.875)"><Density paths={paths[0]} color={INK}/></G>
      {TARGETS.map(target => <G key={target.name}><Rect x={target.x - 3} y={target.y - 3} width={6} height={6} fill="none" stroke={target.color}/><SvgText stroke="#000A" strokeWidth={.55} x={target.x + 6} y={target.y + 3} fontSize={axisSize} fill={target.color}>{target.name}</SvgText></G>)}
      <SvgText stroke="#000A" strokeWidth={.55} x={144} y={143} textAnchor="middle" fill={INK} fontSize={axisSize}>75%</SvgText>
    </G>}
  </Svg>;
});

import React, {useEffect, useMemo, useRef} from 'react';
import {Animated, PanResponder, Pressable, StyleSheet, View} from 'react-native';
import {Text} from 'react-native-paper';
import ScopeControlIcon from './ScopeControlIcon';
import {ui} from '../theme';
import {changeScopePanel, useScopeData} from './useScopes';
import {ScopeBounds, ScopeKind, ScopePanel, ScopePanelState, scopePanelLayout, SCOPE_KINDS, SCOPE_TITLES} from './panelState';
import {ScopeFrame} from './protocol';
import ScopePlot from './ScopePlot';

type ChartProps = {kind: ScopeKind; panel: ScopePanel; bounds: ScopeBounds; data: ScopeFrame | null; stale: boolean; supported: boolean; count: number; selected: boolean};

const ScopeChart = React.memo(function ScopeChart({kind, panel, bounds, data, stale, supported, count, selected}: ChartProps) {
  const layout = scopePanelLayout(bounds, panel.position, panel.size, panel.moved ? undefined : panel.slot, count);
  const drag = useRef(new Animated.ValueXY({x: layout.x, y: layout.y})).current;
  const origin = useRef({x: layout.x, y: layout.y});
  const latest = useRef(layout);latest.current = layout;
  useEffect(() => {drag.setValue({x: layout.x, y: layout.y});}, [drag, layout.x, layout.y]);
  const responder = useMemo(() => {
    const move = (dx: number, dy: number) => {
      const current = latest.current;
      return {x: Math.max(current.minX, Math.min(current.minX + current.travelX, origin.current.x + dx)), y: Math.max(current.minY, Math.min(current.minY + current.travelY, origin.current.y + dy))};
    };
    const save = (dx: number, dy: number) => {
      const point = move(dx, dy), current = latest.current;
      const position = {x: current.travelX ? (point.x - current.minX) / current.travelX : panel.position.x, y: current.travelY ? (point.y - current.minY) / current.travelY : panel.position.y};
      const slot = current.columns === 1 ? panel.slot : Math.round(position.x * (current.columns - 1)) + Math.round(position.y * (current.rows - 1)) * current.columns;
      changeScopePanel({type: 'move', kind, position, slot});
    };
    return PanResponder.create({
      onMoveShouldSetPanResponder: (_, gesture) => Math.abs(gesture.dx) + Math.abs(gesture.dy) > 4,
      onMoveShouldSetPanResponderCapture: (_, gesture) => Math.abs(gesture.dx) + Math.abs(gesture.dy) > 4,
      onPanResponderGrant: () => {origin.current = {x: latest.current.x, y: latest.current.y};changeScopePanel({type: 'raise', kind});},
      onPanResponderMove: (_, gesture) => drag.setValue(move(gesture.dx, gesture.dy)),
      onPanResponderRelease: (_, gesture) => save(gesture.dx, gesture.dy),
      onPanResponderTerminate: (_, gesture) => save(gesture.dx, gesture.dy),
      onPanResponderTerminationRequest: () => false,
    });
  }, [drag, kind, panel.position.x, panel.position.y, panel.slot]);
  const status = !supported ? '当前平台未接入示波器' : !data ? '等待取景数据' : stale ? '取景暂停' : '';
  const resize = () => changeScopePanel({type: 'resize', kind, size: panel.size === 'S' ? 'M' : 'S'});
  if (layout.width < 3 * ui.icon.touch || layout.height < ui.icon.touch + 24) return null;
  return <Animated.View testID={`scope-panel-${kind}`} pointerEvents="box-none" style={[styles.chart, {width: layout.width, height: layout.height, zIndex: panel.layer, transform: drag.getTranslateTransform()}]}>
    <View pointerEvents="none" style={styles.plot}>{data ? <ScopePlot kind={kind} data={data} displayWidth={layout.width} displayHeight={layout.height - 44}/> : <Text style={styles.waiting}>{status}</Text>}</View>
    <View pointerEvents="box-none" style={styles.controls}>
    <View {...responder.panHandlers} style={styles.control}>
    <Pressable testID={`scope-move-${kind}`} accessible accessibilityRole="adjustable" accessibilityLabel={`移动${SCOPE_TITLES[kind]}`}
      accessibilityState={{selected}} onPress={() => changeScopePanel({type: 'raise', kind})} onFocus={() => {if (!selected) changeScopePanel({type: 'raise', kind});}}
      accessibilityHint="点按显示缩放和关闭，拖动以移动图表，或使用无障碍方向操作"
      accessibilityActions={[{name: 'activate', label: '显示图表操作'}, {name: 'left', label: '向左'}, {name: 'right', label: '向右'}, {name: 'up', label: '向上'}, {name: 'down', label: '向下'}]}
      onAccessibilityAction={event => {
        const action = event.nativeEvent.actionName;
        if (action === 'activate') {changeScopePanel({type: 'raise', kind});return;}
        changeScopePanel({type: 'move', kind, position: {
          x: layout.travelX ? (layout.x - layout.minX) / layout.travelX + (action === 'left' ? -.1 : action === 'right' ? .1 : 0) : 0,
          y: layout.travelY ? (layout.y - layout.minY) / layout.travelY + (action === 'up' ? -.1 : action === 'down' ? .1 : 0) : 0,
        }});
      }} style={styles.control}><View pointerEvents="none" style={[styles.icon, selected ? styles.selected : styles.idle]}><ScopeControlIcon name="move" active={selected}/></View></Pressable>
    </View>
    {selected && <>
      <Pressable testID={`scope-resize-${kind}`} accessibilityRole="button" accessibilityLabel={`${panel.size === 'S' ? '放大' : '缩小'}${SCOPE_TITLES[kind]}`} onPress={resize} style={styles.control}>{({pressed}) => <View style={[styles.icon, pressed && styles.pressed]}><ScopeControlIcon name={panel.size === 'S' ? 'enlarge' : 'shrink'}/></View>}</Pressable>
      <Pressable testID={`scope-close-${kind}`} accessibilityRole="button" accessibilityLabel={`关闭${SCOPE_TITLES[kind]}`} onPress={() => changeScopePanel({type: 'close', kind})} style={styles.control}>{({pressed}) => <View style={[styles.icon, pressed && styles.pressed]}><ScopeControlIcon name="close"/></View>}</Pressable>
    </>}
    </View>
    {data && stale && <View pointerEvents="none" style={styles.status}><Text style={styles.waiting}>取景暂停</Text></View>}
  </Animated.View>;
});

export default function ScopesOverlay({panels, bounds, active, rotateClockwise, sourceAspectRatio}: {panels: ScopePanelState; bounds: ScopeBounds; active: boolean; rotateClockwise: boolean; sourceAspectRatio: number}) {
  const open = SCOPE_KINDS.filter(kind => panels[kind].open);
  const {data, stale, supported} = useScopeData(open.length > 0 && active, rotateClockwise, sourceAspectRatio);
  if (!open.length || !bounds.width || !bounds.height) return null;
  const selected = open.reduce((front, kind) => panels[kind].layer > panels[front].layer ? kind : front);
  return <View pointerEvents="box-none" style={StyleSheet.absoluteFill} testID="scopes-overlay">
    {open.map(kind => <ScopeChart key={kind} kind={kind} panel={panels[kind]} bounds={bounds} data={data} stale={stale} supported={supported} count={open.length} selected={selected === kind}/>)}
  </View>;
}

const styles = StyleSheet.create({
  chart: {position: 'absolute', left: 0, top: 0},
  plot: {...StyleSheet.absoluteFillObject, top: 40, bottom: 4, alignItems: 'center', justifyContent: 'center'},
  controls: {position: 'absolute', top: 0, left: 0, flexDirection: 'row'},
  control: {width: ui.icon.touch, height: ui.icon.touch, alignItems: 'center', justifyContent: 'center'},
  icon: {width: 28, height: 28, borderRadius: 14, alignItems: 'center', justifyContent: 'center'},
  selected: {backgroundColor: '#344329CC'}, idle: {opacity: .8}, pressed: {backgroundColor: ui.color.pressed},
  waiting: {...ui.type.label, color: ui.color.text, textShadowColor: '#000', textShadowRadius: 3},
  status: {...StyleSheet.absoluteFillObject, alignItems: 'center', justifyContent: 'center'},
});

export const SCOPE_SHAPE = {histogramBins: 256, waveWidth: 64, levels: 64, paradeWidth: 32, vectorSize: 64} as const;

export type ScopeFrame = {
  version: 1; timestampUs: number; width: number; height: number; rotation: 0 | 90; sourceAspectRatio: number;
  demo: boolean; postLut: true; pixels: number; clipLow: number; clipHigh: number;
  histogram: Uint8Array; waveform: Uint8Array; parade: Uint8Array; vectorscope: Uint8Array;
};

const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const lookup = new Int16Array(128).fill(-1);
for (let i = 0; i < alphabet.length; i++) lookup[alphabet.charCodeAt(i)] = i;

/** Strict, fixed-size decoding without Node Buffer, atob, or an extra RN dependency. */
export function decodeScopeBytes(value: unknown, expectedLength: number): Uint8Array | null {
  if (typeof value !== 'string' || value.length !== 4 * Math.ceil(expectedLength / 3)) return null;
  const out = new Uint8Array(expectedLength);
  let cursor = 0;
  for (let i = 0; i < value.length; i += 4) {
    const last = i + 4 === value.length;
    const remaining = expectedLength - cursor;
    const padding = last ? (3 - remaining) : 0;
    const a = lookup[value.charCodeAt(i)], b = lookup[value.charCodeAt(i + 1)];
    const c = value[i + 2] === '=' ? -1 : lookup[value.charCodeAt(i + 2)];
    const d = value[i + 3] === '=' ? -1 : lookup[value.charCodeAt(i + 3)];
    if (!(a >= 0) || !(b >= 0) || (padding < 2 && !(c >= 0)) || (padding === 0 && !(d >= 0))) return null;
    if ((padding === 2 && (value[i + 2] !== '=' || (b & 15) !== 0)) ||
        (padding >= 1 && value[i + 3] !== '=') || (padding === 1 && (c & 3) !== 0)) return null;
    out[cursor++] = (a << 2) | (b >> 4);
    if (padding < 2) out[cursor++] = (b << 4) | (c >> 2);
    if (padding === 0) out[cursor++] = (c << 6) | d;
  }
  return out;
}

export function decodeScopeFrame(event: unknown): ScopeFrame | null {
  if (!event || typeof event !== 'object') return null;
  const e = event as Record<string, unknown>;
  const integer = (value: unknown, min: number, max: number): value is number =>
    typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
  if (e.version !== 1 || e.postLut !== true || typeof e.demo !== 'boolean' ||
      !integer(e.timestampUs, 0, Number.MAX_SAFE_INTEGER) || !integer(e.width, 1, 256) || !integer(e.height, 1, 256) ||
      (e.rotation !== 0 && e.rotation !== 90) || typeof e.sourceAspectRatio !== 'number' ||
      !Number.isFinite(e.sourceAspectRatio) || e.sourceAspectRatio < .25 || e.sourceAspectRatio > 4 || e.pixels !== e.width * e.height ||
      !integer(e.clipLow, 0, e.pixels as number) || !integer(e.clipHigh, 0, e.pixels as number)) return null;
  const {histogramBins, waveWidth, levels, paradeWidth, vectorSize} = SCOPE_SHAPE;
  const histogram = decodeScopeBytes(e.histogram, 4 * histogramBins);
  const waveform = decodeScopeBytes(e.waveform, waveWidth * levels);
  const parade = decodeScopeBytes(e.parade, 3 * paradeWidth * levels);
  const vectorscope = decodeScopeBytes(e.vectorscope, vectorSize * vectorSize);
  if (!histogram || !waveform || !parade || !vectorscope) return null;
  return {...e, histogram, waveform, parade, vectorscope} as ScopeFrame;
}

import {useEffect, useState, useSyncExternalStore} from 'react';
import {AppState, NativeModules} from 'react-native';
import {cameraEvents} from '../native';
import {createScopePanelState, ScopePanelAction, updateScopePanelState} from './panelState';
import {decodeScopeFrame, ScopeFrame} from './protocol';

// CameraWorkspace unmounts for the album; keep the open set and positions for this JS session.
let session = createScopePanelState();
const listeners = new Set<() => void>();
const subscribe = (listener: () => void) => {listeners.add(listener); return () => {listeners.delete(listener);};};
const snapshot = () => session;
export const changeScopePanel = (action: ScopePanelAction) => {
  session = updateScopePanelState(session, action);
  listeners.forEach(listener => listener());
};
export function useScopePanels() {return useSyncExternalStore(subscribe, snapshot, snapshot);}

type ScopeApi = {setScopesEnabled?: (enabled: boolean, rotateClockwise: boolean, sourceAspectRatio: number) => void};
const scopeApi = NativeModules.MomentLumix as ScopeApi | undefined;

export function useScopeData(requested: boolean, rotateClockwise: boolean, sourceAspectRatio: number) {
  const [foreground, setForeground] = useState(AppState.currentState === 'active');
  const [data, setData] = useState<ScopeFrame | null>(null);
  const [stale, setStale] = useState(false);
  const supported = typeof scopeApi?.setScopesEnabled === 'function' && !!cameraEvents;
  const enabled = requested && foreground && supported;
  useEffect(() => {
    const sub = AppState.addEventListener('change', next => setForeground(next === 'active'));
    return () => sub.remove();
  }, []);
  useEffect(() => {
    setData(null);setStale(false);
    if (!enabled) {scopeApi?.setScopesEnabled?.(false, rotateClockwise, sourceAspectRatio); return;}
    let receivedAt = 0;
    const sub = cameraEvents?.addListener('cameraScopes', (event: unknown) => {
      const decoded = decodeScopeFrame(event);
      if (!decoded || decoded.rotation !== (rotateClockwise ? 90 : 0) || decoded.sourceAspectRatio !== sourceAspectRatio) return;
      receivedAt = Date.now();setData(decoded);setStale(false);
    });
    scopeApi?.setScopesEnabled?.(true, rotateClockwise, sourceAspectRatio);
    const timer = setInterval(() => setStale(receivedAt > 0 && Date.now() - receivedAt > 800), 500);
    return () => {scopeApi?.setScopesEnabled?.(false, rotateClockwise, sourceAspectRatio);sub?.remove();clearInterval(timer);};
  }, [enabled, rotateClockwise, sourceAspectRatio]);
  return {data, stale, supported};
}

import {useEffect, useRef, useState} from 'react';
import {AppState} from 'react-native';

/** A foreground, monotonic countdown that always uses the current capture state. */
export default function useCaptureCountdown(onComplete: () => void, enabled: boolean) {
  const [waiting, setWaiting] = useState(false);
  const [seconds, setSeconds] = useState(0);
  const deadline = useRef<number | null>(null);
  const latest = useRef({onComplete, enabled});
  latest.current = {onComplete, enabled};

  const cancel = () => { deadline.current = null; setWaiting(false); };
  const start = (delay: number) => {
    if (!latest.current.enabled || AppState.currentState !== 'active') return;
    deadline.current = performance.now() + delay * 1000;
    setSeconds(delay); setWaiting(true);
  };

  useEffect(() => { if (!enabled) cancel(); }, [enabled]);
  useEffect(() => {
    const sub = AppState.addEventListener('change', next => { if (next !== 'active') cancel(); });
    return () => { deadline.current = null; sub.remove(); };
  }, []);
  useEffect(() => {
    if (!waiting) return;
    const timer = setInterval(() => {
      if (deadline.current === null) return;
      if (!latest.current.enabled || AppState.currentState !== 'active') { cancel(); return; }
      const left = Math.max(0, Math.ceil((deadline.current - performance.now()) / 1000));
      setSeconds(left);
      if (left === 0) { cancel(); latest.current.onComplete(); }
    }, 100);
    return () => clearInterval(timer);
  }, [waiting]);

  return {waiting, seconds, start, cancel};
}
